def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp_defects = 0
    for h in history:
        if h[1] == 'D':
            opp_defects += 1
    opp_def_rate = opp_defects / n
    if n >= 2:
        if history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'
    if opp_def_rate < 0.2:
        return 'C'
    if history[-1][1] == 'D':
        return 'D'
    return 'C'
